prompt --application/shared_components/logic/application_processes/initialize_user_session
begin
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(162289672216402510910)
,p_process_sequence=>1
,p_process_point=>'AFTER_LOGIN'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'INITIALIZE_USER_SESSION'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    -- This looks up the user in your table and fills the "buckets"',
'    SELECT user_role, user_id ',
'      INTO :F_USER_ROLE, :F_TRADER_ID',
'      FROM HUDDER_USER',
'     WHERE UPPER(email) = UPPER(:APP_USER);',
'',
'EXCEPTION WHEN OTHERS THEN',
'    -- If they aren''t in your table, we set them to guest',
'    :F_USER_ROLE := ''GUEST'';',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_version_scn=>15761541413711
);
end;
