,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ''Active Traders'' AS title,',
'       CAST(COUNT(*) AS VARCHAR2(20)) AS value,',
'       ''of 10 max'' AS subtitle,',
'       ''#APP_FILES#trader.png'' AS icon,',
'       ''active-traders-card'' AS css_class',
'FROM TRADER',
'UNION ALL',
'SELECT ''Customers'',',
'       CAST(COUNT(*) AS VARCHAR2(20)),',
'       ''registered users'',',
'       ''#APP_FILES#customer.png'',',
'       ''customers-card''',
'FROM CUSTOMER',
'UNION ALL',
'SELECT ''Orders Today'',',
'       CAST(COUNT(*) AS VARCHAR2(20)),',
'       ''placed today'',',
'       ''#APP_FILES#order.png'',',
'       ''orders-card''',
'FROM HUDDER_ORDER',
'WHERE order_date = TRUNC(SYSDATE)',
'UNION ALL',
'SELECT ''Revenue This Week'',',
unistr('       ''\00A3'' || CAST(NVL(SUM(amount),0) AS VARCHAR2(20)),'),
'       ''this week'',',
'       ''#APP_FILES#revenue.png'',',
'       ''revenue-card''',
'FROM PAYMENT',
'WHERE payment_date >= TRUNC(SYSDATE, ''IW'');'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_plug_query_num_rows_type=>'SCROLL'
,p_show_total_row_count=>false
);
