'SELECT ',
'    ''New customer registered'' AS list_title,',
'    firstname || '' '' || lastname AS list_text',
'FROM HUDDER_USER ',
'WHERE user_role = ''customer'' AND ROWNUM <= 1',
'UNION ALL',
'-- New Orders',
'SELECT ',
'    ''New order #'' || order_id,',
'    ''Status: '' || status',
'FROM HUDDER_ORDER ',
'WHERE ROWNUM <= 1',
'UNION ALL',
'-- Low Stock Alert',
'SELECT ',
'    ''Low stock alert'',',
'    name || '' (Stock: '' || stock || '')''',
