wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(152405165187269900706)
,p_plug_name=>'Customer Status'
,p_title=>'Customer Stats'
,p_region_template_options=>'#DEFAULT#:t-CardsRegion--hideHeader js-addHiddenHeadingRoleDesc'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>2072724515482255512
,p_plug_display_sequence=>70
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'WITH top_customer_stats AS (',
'    SELECT ',
'        u.firstname, ',
'        u.lastname, ',
'        COUNT(o.order_id) as total_orders,',
'        SUBSTR(u.firstname, 1, 1) || SUBSTR(u.lastname, 1, 1) as initials',
'    FROM HUDDER_USER u',
'    JOIN HUDDER_ORDER o ON u.user_id = o.user_id',
'    GROUP BY u.user_id, u.firstname, u.lastname',
'    ORDER BY total_orders DESC, u.firstname ASC',
'    FETCH FIRST 1 ROWS ONLY',
')',
'SELECT ',
'    ''Total customers'' as card_title,',
'    TO_CHAR((SELECT COUNT(*) FROM CUSTOMER)) as card_value,',
'    ''+5 this week'' as card_subtext, ',
'    ''https://img.icons8.com/color/96/group.png'' as card_icon, ',
'    ''card-green'' as card_class',
'FROM DUAL',
'UNION ALL',
'SELECT ',
'    ''Orders this month'',',
'    TO_CHAR((SELECT COUNT(*) FROM HUDDER_ORDER WHERE TRUNC(order_date, ''MM'') = TRUNC(SYSDATE, ''MM''))),',
'    ''Avg '' || ROUND((SELECT COUNT(*) FROM HUDDER_ORDER) / NULLIF((SELECT COUNT(*) FROM CUSTOMER),0), 1) || '' per customer'',',
'    ''https://cdn-icons-png.flaticon.com/512/2331/2331970.png'' as card_icon,',
'    ''card-blue''',
'FROM DUAL',
'UNION ALL',
'SELECT ',
'    ''Blocked'',',
'    TO_CHAR((SELECT COUNT(*) FROM TRADER WHERE status = ''Pending'')),',
'    ''Check pending traders'',',
'    ''https://cdn-icons-png.flaticon.com/512/1828/1828843.png'' as card_icon,',
'    ''card-red''',
'FROM DUAL',
'UNION ALL',
'SELECT ',
'    ''Top customer'',',
'    (SELECT initials FROM top_customer_stats),',
unistr('    (SELECT firstname || '' '' || lastname || '' \00B7 '' || total_orders || '' orders'' FROM top_customer_stats), '),
'    ''https://img.icons8.com/color/96/star--v1.png'' as card_icon,',
'    ''card-yellow''',
'FROM DUAL;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_plug_query_num_rows_type=>'SCROLL'
,p_show_total_row_count=>false
);
