wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(162695843372358998036)
,p_plug_name=>'Trader Administration'
,p_title=>'Trader Administration'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>4072358936313175081
,p_plug_display_sequence=>10
,p_location=>null
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    -- Variable to handle CSS class logic',
'    v_class_name VARCHAR2(100);',
'    v_modal_url  VARCHAR2(1000);',
'',
'    -- 1. CURSOR FOR PENDING TRADERS',
'    CURSOR c_pending IS',
'        SELECT t.trader_id, ',
'               u.firstname || '' '' || u.lastname as owner_name, ',
'               s.name as shop_name, ',
'               u.email, ',
'               t.status',
'        FROM TRADER t',
'        JOIN HUDDER_USER u ON t.user_id = u.user_id',
'        LEFT JOIN SHOP s ON u.user_id = s.user_id',
'        WHERE t.status = ''Pending''',
'        ORDER BY t.trader_id DESC;',
'',
'    -- 2. CURSOR FOR ACTIVE TRADERS',
'    CURSOR c_active IS',
'        SELECT t.trader_id, ',
'               u.firstname || '' '' || u.lastname as owner_name, ',
'               s.name as shop_name, ',
'               t.status,',
'               (SELECT ROUND(AVG(r.rating), 1) ',
'                FROM REVIEW r ',
'                JOIN PRODUCT p ON r.product_id = p.product_id ',
'                WHERE p.shop_id = s.shop_id) as avg_rating',
'        FROM TRADER t',
'        JOIN HUDDER_USER u ON t.user_id = u.user_id',
'        JOIN SHOP s ON u.user_id = s.user_id',
'        WHERE t.status = ''Active''',
'        ORDER BY avg_rating ASC;',
'',
'BEGIN',
'    -- CSS STYLING',
'    HTP.P(''<style>',
'        .admin-wrap { font-family: "Segoe UI", sans-serif; max-width: 1200px; margin: auto; }',
'        .sect-header { background: #2d5a3f; color: white; padding: 12px 20px; margin-top: 30px; border-radius: 6px 6px 0 0; font-weight: 600; text-transform: uppercase; letter-spacing: 1px; }',
'        .trader-card { border: 1px solid #e0e0e0; border-top: none; padding: 20px; display: flex; justify-content: space-between; align-items: center; background: #ffffff; transition: 0.3s; }',
'        .trader-card:hover { background: #f9f9f9; box-shadow: inset 4px 0 0 #2d5a3f; }',
'        ',
'        .info-box h4 { margin: 0 0 8px 0; font-size: 1.25em; }',
'        /* Link styling moved to Trader Name */',
'        .trader-link { color: #2d5a3f; text-decoration: underline; font-weight: bold; cursor: pointer; transition: 0.2s; }',
'        .trader-link:hover { color: #1a3324; text-decoration: none; }',
'        ',
'        .info-box p { margin: 3px 0; color: #555; font-size: 0.95em; }',
'        .tag-pending { background: #fff3e0; color: #ef6c00; font-size: 0.65em; padding: 3px 8px; border-radius: 10px; margin-left: 10px; vertical-align: middle; border: 1px solid #ffe0b2;}',
'        .rating-chip { background: #ffc107; color: #000; padding: 4px 10px; border-radius: 4px; font-weight: bold; }',
'        .bad-rating-alert { background: #fff5f5 !important; border-left: 6px solid #dc3545 !important; }',
'        ',
'        .btn-act { padding: 10px 18px; border-radius: 5px; cursor: pointer; color: white !important; font-weight: 600; text-decoration: none !important; display: inline-block; transition: 0.2s; font-size: 0.9em; border: none; }',
'        .btn-act:hover { opacity: 0.8; transform: translateY(-1px); }',
'        .b-acc { background: #28a745; margin-right: 8px; }',
'        .b-dec { background: #dc3545; }',
'        .b-blk { background: #343a40; }',
'    </style>'');',
'',
'    HTP.P(''<div class="admin-wrap">'');',
'',
'    -- SECTION 1: PENDING REGISTRATIONS',
'    HTP.P(''<div class="sect-header">Pending Trader Requests</div>'');',
'    ',
'    FOR r IN c_pending LOOP',
'        -- Fixed URL with 4 colons',
'        v_modal_url := APEX_UTIL.PREPARE_URL(''f?p=''||:APP_ID||'':4:''||:APP_SESSION||''::::P4_TRADER_ID:''||r.trader_id);',
'',
'        HTP.P(''<div class="trader-card">'');',
'        HTP.P(''<div class="info-box">'');',
'        -- TRADER NAME is now the primary clickable link',
'        HTP.P(''<h4><a href="'' || v_modal_url || ''" class="trader-link">'' || r.owner_name || ''</a> <span class="tag-pending">PENDING APPROVAL</span></h4>'');',
'        -- SHOP NAME moved to info line',
'        HTP.P(''<p><strong>Shop:</strong> '' || r.shop_name || '' | <strong>Email:</strong> '' || r.email || ''</p>'');',
'        HTP.P(''</div>'');',
'        ',
'        HTP.P(''<div class="actions">'');',
'        HTP.P(''<a href="'' || APEX_UTIL.PREPARE_URL(''f?p=''||:APP_ID||'':''||:APP_PAGE_ID||'':''||:APP_SESSION||'':ACCEPT:''||NVL(:DEBUG,''NO'')||''::P3_SELECTED_TRADER_ID:''||r.trader_id) || ''" class="btn-act b-acc">ACCEPT</a>'');',
'        HTP.P(''<a href="'' || APEX_UTIL.PREPARE_URL(''f?p=''||:APP_ID||'':''||:APP_PAGE_ID||'':''||:APP_SESSION||'':DECLINE:''||NVL(:DEBUG,''NO'')||''::P3_SELECTED_TRADER_ID:''||r.trader_id) || ''" class="btn-act b-dec" onclick="return confirm(''''Delete this regist'
||'ration record?'''')">DECLINE</a>'');',
'        HTP.P(''</div></div>'');',
'    END LOOP;',
'',
'    -- SECTION 2: ACTIVE TRADERS',
'    HTP.P(''<div class="sect-header" style="margin-top:40px;">Manage Active Traders</div>'');',
'',
'    FOR r IN c_active LOOP',
'        v_class_name := ''trader-card'';',
'        IF r.avg_rating < 3.0 THEN v_class_name := v_class_name || '' bad-rating-alert''; END IF;',
'        ',
'        v_modal_url := APEX_UTIL.PREPARE_URL(''f?p=''||:APP_ID||'':4:''||:APP_SESSION||''::::P4_TRADER_ID:''||r.trader_id);',
'',
'        HTP.P(''<div class="'' || v_class_name || ''">'');',
'        HTP.P(''<div class="info-box">'');',
'        -- TRADER NAME is now the primary clickable link',
'        HTP.P(''<h4><a href="'' || v_modal_url || ''" class="trader-link">'' || r.owner_name || ''</a></h4>'');',
'        -- SHOP NAME and RATING moved to info line',
'        HTP.P(''<p><strong>Shop:</strong> '' || r.shop_name || '' | <strong>Rating:</strong> <span class="rating-chip">'' || NVL(TO_CHAR(r.avg_rating), ''No Reviews'') || ''</span></p>'');',
'        HTP.P(''</div>'');',
'        ',
'        HTP.P(''<div class="actions">'');',
'        HTP.P(''<a href="'' || APEX_UTIL.PREPARE_URL(''f?p=''||:APP_ID||'':''||:APP_PAGE_ID||'':''||:APP_SESSION||'':BLOCK:''||NVL(:DEBUG,''NO'')||''::P3_SELECTED_TRADER_ID:''||r.trader_id) || ''" class="btn-act b-blk" onclick="return confirm(''''Block this trader ac'
||'count?'''')">BLOCK TRADER</a>'');',
'        HTP.P(''</div></div>'');',
'    END LOOP;',
'',
'    HTP.P(''</div>'');',
'END;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
);
wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(162695843417454998037)
,p_name=>'P3_SELECTED_TRADER_ID'
,p_item_sequence=>10
,p_item_plug_id=>wwv_flow_imp.id(162695843372358998036)
,p_display_as=>'NATIVE_HIDDEN'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'value_protected', 'N')).to_clob
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(162695843555135998038)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Handle Trader Actions'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    -- Only run if an ID has been passed via the button click',
'    IF :P3_SELECTED_TRADER_ID IS NOT NULL THEN',
'        ',
'        CASE :REQUEST',
'            --------------------------------------------------------------------',
'            -- 1. ACCEPT ACTION: Move trader to Active list',
'            --------------------------------------------------------------------',
'            WHEN ''ACCEPT'' THEN',
'                UPDATE TRADER ',
'                SET status = ''Active'' ',
'                WHERE trader_id = :P3_SELECTED_TRADER_ID;',
'                ',
'                APEX_APPLICATION.G_PRINT_SUCCESS_MESSAGE := ''Trader accepted. They are now in the Active list.'';',
'',
'            --------------------------------------------------------------------',
'            -- 2. DECLINE ACTION: Completely remove records (Cascade Delete)',
'            --------------------------------------------------------------------',
'            WHEN ''DECLINE'' THEN',
'                -- A. First, find the User ID and Shop ID associated with this Trader',
'                DECLARE',
'                    v_user_id NUMBER;',
'                    v_shop_id NUMBER;',
'                BEGIN',
'                    SELECT user_id INTO v_user_id FROM TRADER WHERE trader_id = :P3_SELECTED_TRADER_ID;',
'                    ',
'                    BEGIN',
'                        SELECT shop_id INTO v_shop_id FROM SHOP WHERE user_id = v_user_id;',
'                    EXCEPTION WHEN NO_DATA_FOUND THEN v_shop_id := NULL;',
'                    END;',
'',
'                    -- B. Delete child records to avoid Foreign Key errors',
'                    IF v_shop_id IS NOT NULL THEN',
'                        -- Remove reviews of this shop''s products',
'                        DELETE FROM REVIEW WHERE product_id IN (SELECT product_id FROM PRODUCT WHERE shop_id = v_shop_id);',
'                        -- Remove cart items for this shop''s products',
'                        DELETE FROM CART_ITEM WHERE product_id IN (SELECT product_id FROM PRODUCT WHERE shop_id = v_shop_id);',
'                        -- Remove the products themselves',
'                        DELETE FROM PRODUCT WHERE shop_id = v_shop_id;',
'                        -- Remove the shop',
'                        DELETE FROM SHOP WHERE shop_id = v_shop_id;',
'                    END IF;',
'',
'                    -- C. Remove the Trader record',
'                    DELETE FROM TRADER WHERE trader_id = :P3_SELECTED_TRADER_ID;',
'                    ',
'                    -- Optional: If you want to delete the login account as well:',
'                    -- DELETE FROM HUDDER_USER WHERE user_id = v_user_id;',
'                END;',
'',
'                APEX_APPLICATION.G_PRINT_SUCCESS_MESSAGE := ''Trader registration declined and records cleared.'';',
'',
'            --------------------------------------------------------------------',
'            -- 3. BLOCK ACTION: Set status to Blocked',
'            --------------------------------------------------------------------',
'            WHEN ''BLOCK'' THEN',
'                UPDATE TRADER ',
'                SET status = ''Blocked'' ',
'                WHERE trader_id = :P3_SELECTED_TRADER_ID;',
'                ',
'                APEX_APPLICATION.G_PRINT_SUCCESS_MESSAGE := ''Trader account has been successfully blocked.'';',
'',
'            ELSE',
'                NULL;',
'        END CASE;',
'',
'        -- FINAL STEP: Clear the item so it doesn''t re-run on page refresh',
'        :P3_SELECTED_TRADER_ID := NULL;',
'',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>162695843555135998038
);
end;
/
