wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(152405167242752900727)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Load Trader Details'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    IF :P4_TRADER_ID IS NOT NULL THEN',
'        SELECT',
'            s.name,',
'            s.description,',
'            s.location,',
'            s.contact_number,',
'            u.firstname || '' '' || u.lastname,',
'            u.email,',
'            t.status',
'        INTO',
'            :P4_SHOP_NAME,',
'            :P4_SHOP_DESC,',
'            :P4_SHOP_LOCATION,',
'            :P4_CONTACT,',
'            :P4_OWNER,',
'            :P4_EMAIL,',
'            :P4_STATUS',
'        FROM TRADER t',
'        JOIN HUDDER_USER u ON t.user_id = u.user_id',
'        LEFT JOIN SHOP s ON s.user_id = u.user_id',
'        WHERE t.trader_id = :P4_TRADER_ID',
'        AND ROWNUM = 1;',
'    END IF;',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        -- Optionally clear items if no trader found',
'        :P4_SHOP_NAME := ''No Data Found'';',
'    WHEN OTHERS THEN',
'        NULL; -- Ignore other errors to keep page loading',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_when=>'P4_TRADER_ID'
,p_process_when_type=>'ITEM_IS_NOT_NULL'
,p_internal_uid=>152405167242752900727
);
end;
/
