wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(152405168026016900735)
,p_plug_name=>'New'
,p_title=>'Products'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>2100526641005906379
,p_plug_display_sequence=>30
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    p.product_id         AS "Id",',
'    p.name               AS "Product",',
'    p.description        AS "Description",',
'    p.price              AS "Price",',
'    p.stock              AS "Stock",',
'    pc.category_name     AS "Category",',
'    s.name               AS "Shop",',
'    u.firstname || '' '' || u.lastname AS "Trader",',
'    p.status             AS "Status"',
'FROM PRODUCT p',
'JOIN SHOP s ON p.shop_id = s.shop_id',
'JOIN HUDDER_USER u ON s.user_id = u.user_id',
'LEFT JOIN PRODUCT_CATEGORY pc ON p.category_id = pc.category_id',
'WHERE (',
'    -- 1. TRADER LOGIC: Oliver sees all his products (Active or Pending)',
'    -- Using :F_TRADER_ID which we confirmed is set to ''1''',
'    (UPPER(:F_USER_ROLE) = ''TRADER'' AND u.user_id = :F_TRADER_ID)',
'    OR',
'    -- 2. ADMIN LOGIC: ',
'    (UPPER(:F_USER_ROLE) = ''ADMIN'' AND (',
'        -- Selected from dropdown',
'        (u.user_id = :P5_TRADER_SELECTOR) ',
'        OR ',
'        -- Global view: show only approved Active products',
'        (:P5_TRADER_SELECTOR IS NULL AND p.status = ''Active'')',
'    ))',
')',
'ORDER BY p.product_id'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P5_TRADER_SELECTOR'
