wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(158694541481711037304)
,p_plug_name=>'Category_card'
,p_region_template_options=>'#DEFAULT#:t-CardsRegion--hideHeader js-addHiddenHeadingRoleDesc'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>2072724515482255512
,p_plug_display_sequence=>20
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    pc.category_name as card_title,',
'    count(p.product_id) as item_count,',
'    -- Mapping emojis including your new categories',
'    CASE pc.category_name',
unistr('        WHEN ''Delicatessen''      THEN ''\D83E\DDC0'''),
unistr('        WHEN ''Butcher''           THEN ''\D83E\DD69'''),
unistr('        WHEN ''Greengrocer''       THEN ''\D83E\DD55'''),
unistr('        WHEN ''Fishmonger''        THEN ''\D83D\DC1F'''),
unistr('        WHEN ''Bakery''            THEN ''\D83E\DD56'''),
unistr('        WHEN ''Honey & Preserves'' THEN ''\D83C\DF6F'''),
unistr('        WHEN ''Herbs & Spices''    THEN ''\D83C\DF3F'''),
unistr('        ELSE ''\D83D\DCE6'''),
'    END as cute_emoji,',
'    pc.category_id as pk_id',
'FROM PRODUCT_CATEGORY pc',
'JOIN PRODUCT p ON pc.category_id = p.category_id',
'JOIN SHOP s    ON p.shop_id = s.shop_id',
'WHERE (',
'    -- 1. TRADER LOGIC: Match the trader ID from session state',
'    (:F_USER_ROLE = ''trader'' AND s.user_id = :F_TRADER_ID)',
'    OR',
'    -- 2. ADMIN LOGIC:',
'    (:F_USER_ROLE = ''admin'' AND (',
'        -- Filtered by dropdown',
'        (s.user_id = :P5_TRADER_SELECTOR) ',
'        OR ',
'        -- Global view: Only approved (Active) products',
'        (:P5_TRADER_SELECTOR IS NULL AND p.status = ''Active'')',
'    ))',
')',
'GROUP BY pc.category_name, pc.category_id',
'ORDER BY pc.category_name'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_ajax_items_to_submit=>'P5_TRADER_SELECTOR'
,p_plug_query_num_rows_type=>'SCROLL'
,p_show_total_row_count=>false
);
