wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(162695843733266998040)
,p_plug_name=>'Product Approvals'
,p_title=>'Product Approvals (Admin Only)'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>4072358936313175081
,p_plug_display_sequence=>5
,p_location=>null
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    -- Cursor to fetch products that need admin approval',
'    CURSOR c_pending_prods IS',
'        SELECT p.product_id, ',
'               p.name as product_name, ',
'               s.name as shop_name, ',
'               u.firstname || '' '' || u.lastname as trader_name,',
'               p.price',
'        FROM PRODUCT p',
'        JOIN SHOP s ON p.shop_id = s.shop_id',
'        JOIN HUDDER_USER u ON s.user_id = u.user_id',
'        WHERE p.status = ''Pending''',
'        ORDER BY p.product_id DESC;',
'',
'BEGIN',
'    -- Styling (Hudders Hub Green Theme)',
'    HTP.P(''<style>',
'        .prod-admin-wrap { font-family: "Segoe UI", sans-serif; margin-bottom: 40px; }',
'        .prod-sect-header { background: #2d5a3f; color: white; padding: 12px 20px; border-radius: 6px 6px 0 0; font-weight: 600; text-transform: uppercase; letter-spacing: 1px; }',
'        .prod-card { border: 1px solid #e0e0e0; border-top: none; padding: 20px; display: flex; justify-content: space-between; align-items: center; background: #ffffff; transition: 0.3s; }',
'        .prod-card:hover { background: #fdfdfd; box-shadow: inset 4px 0 0 #28a745; }',
'        .prod-card:last-child { border-radius: 0 0 6px 6px; }',
'        ',
'        .p-info h5 { margin: 0 0 5px 0; color: #2d5a3f; font-size: 1.15em; font-weight: bold; }',
'        .p-info p { margin: 2px 0; color: #666; font-size: 0.9em; }',
'        .p-price { color: #28a745; font-weight: bold; margin-left: 10px; }',
'        ',
'        .p-actions { display: flex; gap: 10px; }',
'        .p-btn { padding: 8px 16px; border-radius: 4px; color: white !important; font-weight: 600; text-decoration: none !important; font-size: 0.85em; border: none; transition: 0.2s; }',
'        .p-btn:hover { opacity: 0.85; transform: translateY(-1px); }',
'        .p-appr { background: #28a745; }',
'        .p-rejt { background: #dc3545; }',
'    </style>'');',
'',
'    HTP.P(''<div class="prod-admin-wrap">'');',
'    HTP.P(''<div class="prod-sect-header">Product Approval Queue</div>'');',
'',
'    FOR r IN c_pending_prods LOOP',
'        HTP.P(''<div class="prod-card">'');',
'        ',
'        HTP.P(''<div class="p-info">'');',
