wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(162695843986100998042)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Handle Product Approvals'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    IF :P5_PROD_ID_TEMP IS NOT NULL THEN',
'        CASE :REQUEST',
'            WHEN ''APPROVE_PROD'' THEN',
'                -- Set status to Active so it appears in the shop',
'                UPDATE PRODUCT ',
'                SET status = ''Active'' ',
'                WHERE product_id = :P5_PROD_ID_TEMP;',
'                ',
'                APEX_APPLICATION.G_PRINT_SUCCESS_MESSAGE := ''Product approved successfully.'';',
'',
'            WHEN ''REJECT_PROD'' THEN',
'                -- Delete the product as it was rejected',
'                DELETE FROM PRODUCT ',
'                WHERE product_id = :P5_PROD_ID_TEMP;',
'                ',
'                APEX_APPLICATION.G_PRINT_SUCCESS_MESSAGE := ''Product rejected and removed.'';',
'            ELSE',
'                NULL;',
'        END CASE;',
'',
'        -- Clear the temp ID',
'        :P5_PROD_ID_TEMP := NULL;',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>wwv_flow_imp.id(161987846495399780385)
,p_internal_uid=>162695843986100998042
);
end;
