wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(154395401338333805907)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Load Product Details Process'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    SELECT',
'        p.name,',
'        p.description,',
'        pc.category_name,',
'        p.price,',
'        p.stock,',
'        p.min_order,',
'        p.max_order,',
'        p.allergen_info,',
'        s.name,',
'        u.firstname || '' '' || u.lastname',
'    INTO',
'        :P6_PRODUCT_NAME,',
'        :P6_DESCRIPTION,',
'        :P6_CATEGORY,',
'        :P6_PRICE,',
'        :P6_STOCK,',
'        :P6_MIN_ORDER,',
'        :P6_MAX_ORDER,',
'        :P6_ALLERGEN,',
'        :P6_SHOP,',
'        :P6_TRADER',
'    FROM PRODUCT p',
'    JOIN SHOP s ON p.shop_id = s.shop_id',
'    JOIN HUDDER_USER u ON s.user_id = u.user_id',
'    LEFT JOIN PRODUCT_CATEGORY pc ON p.category_id = pc.category_id',
'    WHERE p.product_id = :P6_PRODUCT_ID;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>154395401338333805907
);
end;
