'.rpt-card-header {',
'  text-align: center;',
'  border-bottom: 1.5px solid #1a1a1a;',
'  padding-bottom: 1rem;',
'  margin-bottom: 1.5rem;',
'}',
'',
'.rpt-card-title {',
'  font-size: 20px;',
'  font-weight: 600;',
'  letter-spacing: 0.3px;',
'}',
'',
'.rpt-meta {',
'  font-size: 13px;',
'  color: #555;',
'  margin-top: 10px;',
'  display: flex;',
'  align-items: center;',
'  justify-content: center;',
'  gap: 12px;',
