'}',
'',
'.rpt-date-input, .rpt-select-trader {',
'  font-size: 12px;',
'  font-family: Arial, sans-serif;',
'  border: 1px solid #aaa;',
'  border-radius: 3px;',
'  padding: 3px 8px;',
'  color: #222;',
'  background: #fff;',
