'}',
'',
'.btn-generate {',
'  font-size: 12px;',
'  background: #1a1a1a;',
'  color: #fff;',
'  border: none;',
'  padding: 4px 12px;',
'  border-radius: 3px;',
'  cursor: pointer;',
'  font-family: Arial, sans-serif;',
'}',
'.btn-generate:hover { background: #444; }',
'',
'.slot-block { margin-bottom: 1.5rem; }',
'',
'.slot-label {',
'  font-size: 12px;',
