'}',
'',
'.slot-table thead tr { background: #f0ede6; }',
'',
'.slot-table th {',
'  padding: 8px 12px;',
'  text-align: left;',
'  font-weight: 600;',
'  font-size: 13px;',
'  color: #333;',
'  border-bottom: 1px solid #ccc;',
'}',
'',
'.slot-table td {',
'  padding: 8px 12px;',
'  border-bottom: 1px solid #eee;',
'  color: #222;',
'}',
'',
'.customer-list { display: flex; gap: 6px; flex-wrap: wrap; }',
'',
'.customer-badge {',
'  font-size: 12px;',
'  background: #f0ede6;',
'  border: 1px solid #d4cfc5;',
'  border-radius: 3px;',
'  padding: 2px 7px;',
'  color: #444;',
'  font-family: Arial, sans-serif;',
'}',
'',
'.no-data {',
'  text-align: center;',
'  padding: 2rem;',
'  font-size: 13px;',
'  color: #888;',
'  font-style: italic;',
'  font-family: Arial, sans-serif;',
'}',
'',
'.labels-section {',
'  border: 1.5px solid #1a1a1a;',
'  border-radius: 4px;',
'  background: #fff;',
'}',
'',
'.labels-header {',
'  text-align: center;',
'  padding: 0.75rem 1rem;',
'  border-bottom: 1.5px solid #1a1a1a;',
'  display: flex;',
'  align-items: center;',
'  justify-content: center;',
'  gap: 14px;',
'}',
'',
'.labels-header::before,',
'.labels-header::after {',
'  content: '''';',
'  height: 1px;',
'  background: #1a1a1a;',
'  flex: 1;',
'}',
'',
'.labels-title {',
'  font-size: 18px;',
