'  white-space: nowrap;',
'}',
'',
'.label-card {',
'  padding: 0.85rem 1.5rem;',
'  border-bottom: 1px solid #eee;',
'}',
'',
'.label-card p {',
'  font-size: 13px;',
'  color: #333;',
'  line-height: 1.9;',
'  font-family: Arial, sans-serif;',
'}',
'',
'.label-actions {',
'  padding: 0.75rem 1.5rem;',
'  display: flex;',
'  gap: 10px;',
'}',
'',
'.btn-action {',
'  font-size: 13px;',
'  background: none;',
'  border: 1px solid #999;',
'  color: #333;',
'  padding: 5px 14px;',
'  border-radius: 3px;',
'  cursor: pointer;',
'  font-family: Arial, sans-serif;',
'  transition: all 0.15s;',
'}',
'.btn-action:hover { background: #1a1a1a; color: #fff; border-color: #1a1a1a; }',
'</style>',
'',
'<div class="rpt-wrapper">',
'  <h1 class="rpt-title">Report</h1>',
'',
'  <div class="rpt-card">',
'    <div class="rpt-card-header">',
'      <div class="rpt-card-title">Daily order report</div>',
'      <div class="rpt-meta">',
'        <span>Date:</span>',
'        <input type="date" id="rptDate" class="rpt-date-input" />',
'        ',
'        <!-- Placeholder for the APEX Select List -->',
'        <span id="traderContainer"></span>',
'',
'        <button type="button" class="btn-generate" onclick="loadDailyReport(event)">Generate</button>',
'      </div>',
'    </div>',
'    <div id="rptBody">',
'      <div class="no-data">Select a date and click Generate to load orders.</div>',
'    </div>',
'  </div>',
'',
'  <div class="labels-section">',
'    <div class="labels-header">',
'      <span class="labels-title">Labels</span>',
'    </div>',
'    <div id="labelsBody">',
'      <div class="no-data">Generate report to see labels.</div>',
'    </div>',
'    <div class="label-actions">',
'      <button type="button" class="btn-action" onclick="window.print()">Print Labels</button>',
'      <button type="button" class="btn-action" onclick="downloadCSV(event)">Download</button>',
'    </div>',
'  </div>',
'</div>',
'',
'<script>',
'var reportData = [];',
'',
'(function() {',
'  // 1. Set default date to today',
'  var d = new Date();',
'  document.getElementById(''rptDate'').value = d.toISOString().slice(0,10);',
'',
'  // 2. Move the APEX Dropdown into our layout if it exists (Admin mode)',
'  var apexDropdown = document.getElementById(''P9_DAILY_SHOP'');',
'  if (apexDropdown) {',
'     var container = document.getElementById(''traderContainer'');',
'     container.innerHTML = ''<span>Trader:</span>'';',
'     container.appendChild(apexDropdown);',
'     apexDropdown.classList.add(''rpt-select-trader'');',
'  }',
'})();',
'',
'function renderReport(rows, displayDate) {',
'  reportData = rows;',
'  var grouped = {};',
'  rows.forEach(function(r) {',
'    if (!grouped[r.SLOT_TIME]) grouped[r.SLOT_TIME] = [];',
'    grouped[r.SLOT_TIME].push(r);',
'  });',
'  ',
'  var html = '''';',
'  var slots = Object.keys(grouped).sort();',
'',
'  if (slots.length === 0) {',
'    document.getElementById(''rptBody'').innerHTML = ''<div class="no-data">No orders found for '' + displayDate + ''.</div>'';',
'    return;',
'  }',
'',
'  slots.forEach(function(slot) {',
'    html += ''<div class="slot-block"><div class="slot-label">Slot: '' + slot + ''</div>'';',
'    html += ''<table class="slot-table"><thead><tr><th>Product</th><th>Qty</th><th>Customer</th></tr></thead><tbody>'';',
'    grouped[slot].forEach(function(row) {',
'      html += ''<tr><td>'' + row.PRODUCT_NAME + ''</td><td>'' + row.TOTAL_QTY + ''</td><td>'' + row.CUSTOMERS + ''</td></tr>'';',
'    });',
'    html += ''</tbody></table></div>'';',
'  });',
'  document.getElementById(''rptBody'').innerHTML = html;',
'}',
'',
'function renderLabels(rows) {',
'  var html = rows.map(function(row) {',
'    return ''<div class="label-card"><p><strong>Order ID:</strong> #'' + row.ORDER_ID + ''<br/><strong>Product:</strong> '' + row.PRODUCT_NAME + ''<br/><strong>Slot:</strong> '' + row.SLOT_LABEL + ''</p></div>'';',
'  }).join('''');',
'  document.getElementById(''labelsBody'').innerHTML = html || ''<div class="no-data">No labels.</div>'';',
'}',
'',
'function loadDailyReport(e) {',
'  if (e) e.preventDefault();',
'  ',
'  var dateVal = document.getElementById(''rptDate'').value; // YYYY-MM-DD',
'  if (!dateVal) return;',
'  var displayDate = dateVal.split(''-'').reverse().join(''/'');',
'',
'  document.getElementById(''rptBody'').innerHTML = ''<div class="no-data">Loading...</div>'';',
'',
'  apex.server.process(''GET_DAILY_ORDERS'', {',
'    pageItems: ''#P9_DAILY_SHOP'', // This grabs the dropdown value if it exists',
'    x01: dateVal',
'  }, {',
'    success: function(data) {',
'      if (data && data.rows) {',
'        renderReport(data.rows, displayDate);',
'        renderLabels(data.rows);',
'      } else {',
'        document.getElementById(''rptBody'').innerHTML = ''<div class="no-data">No data found.</div>'';',
'      }',
'    },',
'    error: function(xhr, status, error) {',
'       document.getElementById(''rptBody'').innerHTML = ''<div class="no-data">Error fetching data.</div>'';',
'       console.log(error);',
'    }',
'  });',
'}',
'',
'function downloadCSV(e) {',
'  if (e) e.preventDefault();',
'  if (!reportData.length) { alert(''No data to download.''); return; }',
'  var csv = ''Order ID,Product,Qty,Customer,Slot\n'' + ',
'      reportData.map(r => r.ORDER_ID + '','' + r.PRODUCT_NAME + '','' + r.TOTAL_QTY + '','' + r.CUSTOMERS + '','' + r.SLOT_TIME).join(''\n'');',
'  var blob = new Blob([csv], { type: ''text/csv'' });',
'  var url = window.URL.createObjectURL(blob);',
'  var a = document.createElement(''a'');',
'  a.setAttribute(''hidden'', '''');',
'  a.setAttribute(''href'', url);',
'  a.setAttribute(''download'', ''daily_report.csv'');',
'  document.body.appendChild(a);',
'  a.click();',
'  document.body.removeChild(a);',
'}',
'</script>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
