wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(158473833602183303937)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GET_DAILY_ORDERS'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_date DATE;',
'BEGIN',
'    -- 1. Get the date from JavaScript',
'    v_date := TO_DATE(apex_application.g_x01, ''YYYY-MM-DD'');',
'',
'    apex_json.open_object;',
'    apex_json.open_array(''rows'');',
'',
'    FOR r IN (',
'        SELECT DISTINCT',
'            o.order_id,',
'            p.name AS product_name,',
'            op.quantity AS total_qty,',
'            u_cust.firstname || '' '' || u_cust.lastname AS customers,',
'            o.order_time AS slot_time,',
'            o.status,',
'            o.order_time || '' ('' || o.status || '')'' AS slot_label',
'        FROM HUDDER_ORDER o',
'        JOIN HUDDER_USER u_cust ON o.user_id = u_cust.user_id',
'        JOIN ORDER_PRODUCT op   ON o.order_id = op.order_id',
'        JOIN PRODUCT p          ON op.product_id = p.product_id',
'        JOIN SHOP s             ON p.shop_id = s.shop_id',
'        WHERE TRUNC(o.order_date) = v_date',
'          AND (',
'                -- Check for Admin (matches ''admin'', ''Admin'', or ''ADMIN'')',
'                (UPPER(:F_USER_ROLE) = ''ADMIN'' AND (s.shop_id = :P9_DAILY_SHOP OR :P9_DAILY_SHOP IS NULL))',
'                OR',
'                -- Check for Trader (matches ''trader'', ''Trader'', etc.)',
'                (UPPER(:F_USER_ROLE) = ''TRADER'' AND s.user_id = :F_TRADER_ID)',
'          )',
'    ) LOOP',
'        apex_json.open_object;',
'        apex_json.write(''ORDER_ID'', r.order_id);',
'        apex_json.write(''PRODUCT_NAME'', r.product_name);',
'        apex_json.write(''TOTAL_QTY'', r.total_qty);',
'        apex_json.write(''CUSTOMERS'', r.customers);',
'        apex_json.write(''SLOT_TIME'', r.slot_time);',
'        apex_json.write(''STATUS'', r.status);',
'        apex_json.write(''SLOT_LABEL'', r.slot_label);',
'        apex_json.close_object;',
'    END LOOP;',
'',
'    apex_json.close_array;',
'    apex_json.close_object;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>158473833602183303937
);
end;
