prompt --application/pages/page_00011
begin
wwv_flow_imp_page.create_page(
 p_id=>11
,p_name=>'Weekly Report'
,p_alias=>'WEEKLY-REPORT'
,p_step_title=>'Weekly Report'
,p_autocomplete_on_off=>'OFF'
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'04'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(158473833769740303938)
,p_plug_name=>'WEEKLY FINANCE REPORT'
,p_title=>'wEEKLY Finance Report'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>4072358936313175081
,p_plug_display_sequence=>10
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<style>',
'/* CSS - Unchanged */',
'*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }',
'body { background: #f7f5f0; }',
'.rpt-wrapper { max-width: 820px; margin: 0 auto; padding: 2rem 1rem; font-family: Georgia, serif; }',
'.rpt-title { font-size: 48px; font-weight: 700; color: #111; margin-bottom: 1.5rem; }',
'.rpt-card { background: #fff; border: 1.5px solid #1a1a1a; border-radius: 4px; padding: 2rem 2rem 1.5rem; margin-bottom: 2rem; }',
'.rpt-card-header { text-align: center; border-bottom: 1.5px solid #1a1a1a; padding-bottom: 1rem; margin-bottom: 1.5rem; }',
'.rpt-card-title { font-size: 20px; font-weight: 600; letter-spacing: 0.3px; }',
'.rpt-meta { font-size: 13px; color: #555; margin-top: 5px; display: flex; align-items: center; justify-content: center; gap: 12px; font-family: Arial, sans-serif; flex-wrap: wrap; }',
'.rpt-date-input, .rpt-select-trader { font-size: 12px; font-family: Arial, sans-serif; border: 1px solid #aaa; border-radius: 3px; padding: 3px 8px; color: #222; background: #fff; }',
'.btn-generate { font-size: 12px; background: #1a1a1a; color: #fff; border: none; padding: 4px 12px; border-radius: 3px; cursor: pointer; }',
'.slot-table { width: 100%; border-collapse: collapse; border: 1px solid #ccc; font-size: 14px; font-family: Arial, sans-serif; }',
'.slot-table thead tr { background: #f0ede6; }',
'.slot-table th, .slot-table td { padding: 8px 12px; border-bottom: 1px solid #eee; text-align: left; }',
'.total-row td { font-weight: 600; background: #f0ede6; border-top: 1.5px solid #ccc; }',
'.no-data { text-align: center; padding: 2rem; font-size: 13px; color: #888; font-style: italic; }',
'.label-actions { padding: 0.75rem 0; display: flex; gap: 10px; }',
'.btn-action { font-size: 13px; background: none; border: 1px solid #999; padding: 5px 14px; border-radius: 3px; cursor: pointer; transition: 0.15s; }',
'.btn-action:hover { background: #1a1a1a; color: #fff; }',
'</style>',
'',
'<div class="rpt-wrapper">',
'  <h1 class="rpt-title">Weekly Finance Report</h1>',
'  <div class="rpt-card">',
'    <div class="rpt-card-header">',
'      <div class="rpt-card-title">Weekly summary</div>',
'      <div class="rpt-meta">',
'        <span>Week ending:</span>',
'        <input type="date" id="rptDate" class="rpt-date-input" />',
'        <!-- Dropdown placeholder for Admin -->',
'        <span id="traderContainer"></span>',
'        <button type="button" class="btn-generate" onclick="loadWeeklyReport(event)">Generate</button>',
'      </div>',
'    </div>',
'    <div id="rptBody">',
'      <div class="no-data">Select a week ending date and click Generate.</div>',
'    </div>',
'    <div class="label-actions">',
'      <button type="button" class="btn-action" onclick="downloadCSV(event)">Download CSV</button>',
'    </div>',
'  </div>',
'</div>',
'',
'<script>',
'var reportData = [];',
'',
'(function() {',
'  // 1. Set default date to today',
'  var d = new Date();',
'  document.getElementById(''rptDate'').value = d.toISOString().slice(0,10);',
'',
'  // 2. Move APEX dropdown if it exists (Admin Only)',
'  var apexDropdown = document.getElementById(''P11_WEEKLY_SHOP'');',
'  if (apexDropdown) {',
'     var container = document.getElementById(''traderContainer'');',
'     container.innerHTML = ''<span>Trader:</span>'';',
'     container.appendChild(apexDropdown);',
'     apexDropdown.classList.add(''rpt-select-trader'');',
'  }',
'})();',
'',
'function renderReport(rows) {',
'  reportData = rows;',
unistr('  var html = ''<table class="slot-table"><thead><tr><th>Trader</th><th>Shop</th><th>Orders Delivered</th><th>Total Payment (\00A3)</th></tr></thead><tbody>'';'),
'  var grandTotal = 0;',
'  rows.forEach(function(row) {',
'    grandTotal += parseFloat(row.TOTAL_PAYMENT);',
unistr('    html += ''<tr><td>''+row.TRADER_NAME+''</td><td>''+row.SHOP_NAME+''</td><td>''+row.ORDER_COUNT+''</td><td>\00A3''+parseFloat(row.TOTAL_PAYMENT).toFixed(2)+''</td></tr>'';'),
'  });',
unistr('  html += ''<tr class="total-row"><td colspan="3">Grand Total</td><td>\00A3''+grandTotal.toFixed(2)+''</td></tr></tbody></table>'';'),
'  document.getElementById(''rptBody'').innerHTML = html;',
'}',
'',
'function loadWeeklyReport(e) {',
'  if (e) e.preventDefault();',
'  var val = document.getElementById(''rptDate'').value;',
'  if (!val) return;',
'',
'  document.getElementById(''rptBody'').innerHTML = ''<div class="no-data">Loading...</div>'';',
'',
'  apex.server.process(''GET_WEEKLY_FINANCE'', {',
'    pageItems: ''#P11_WEEKLY_SHOP'', // Submit the Page 11 dropdown',
'    x01: val',
'  }, {',
'    success: function(data) {',
'      if (data && data.rows && data.rows.length > 0) {',
'        renderReport(data.rows);',
'      } else {',
'        document.getElementById(''rptBody'').innerHTML = ''<div class="no-data">No delivered orders found for this week.</div>'';',
'      }',
'    }',
'  });',
'}',
'',
'function downloadCSV(e) {',
'  if (e) e.preventDefault();',
'  if (!reportData.length) return;',
'  var csv = ''Trader,Shop,Orders,Total\n'' + reportData.map(r => r.TRADER_NAME+'',''+r.SHOP_NAME+'',''+r.ORDER_COUNT+'',''+r.TOTAL_PAYMENT).join(''\n'');',
'  var a = document.createElement(''a'');',
'  a.href = ''data:text/csv;charset=utf-8,'' + encodeURIComponent(csv);',
'  a.download = ''weekly_finance.csv'';',
'  a.click();',
'}',
'</script>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
