,p_prompt=>'Weekly Shop'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT u.firstname || '' '' || u.lastname AS d, s.shop_id AS r',
'FROM HUDDER_USER u JOIN SHOP s ON u.user_id = s.user_id',
'WHERE u.user_role = ''trader'' ORDER BY 1'))
,p_lov_display_null=>'YES'
,p_lov_null_text=>'- All Traders -'
,p_cHeight=>1
,p_field_template=>2318601014859922299
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'YES'
,p_security_scheme=>wwv_flow_imp.id(161987846495399780385)
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(158473833882820303939)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GET_WEEKLY_FINANCE'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  l_end_date   DATE := TO_DATE(apex_application.g_x01, ''YYYY-MM-DD'');',
'  l_start_date DATE := l_end_date - 6;',
'BEGIN',
'  APEX_JSON.OPEN_OBJECT;',
'  APEX_JSON.OPEN_ARRAY(''rows'');',
'',
'  FOR r IN (',
'    SELECT',
'      u.firstname || '' '' || u.lastname   AS trader_name,',
'      s.name                             AS shop_name,',
'      COUNT(DISTINCT o.order_id)         AS order_count,',
'      SUM(op.quantity * op.unit_price)   AS total_payment',
'    FROM HUDDER_ORDER o',
'    JOIN ORDER_PRODUCT op  ON op.order_id  = o.order_id',
'    JOIN PRODUCT p         ON p.product_id = op.product_id',
'    JOIN SHOP s            ON s.shop_id    = p.shop_id',
'    JOIN HUDDER_USER u     ON u.user_id    = s.user_id',
'    WHERE TRUNC(o.order_date) BETWEEN TRUNC(l_start_date) AND TRUNC(l_end_date)',
'    -- Your statuses are ''Pending'', ''Completed'', ''Cancelled''. Using ''Completed'' as the trigger.',
'    AND o.status = ''Completed'' ',
'    AND (',
'          -- Admin Logic',
'          (UPPER(:F_USER_ROLE) = ''ADMIN'' AND (s.shop_id = :P11_WEEKLY_SHOP OR :P11_WEEKLY_SHOP IS NULL))',
'          OR',
'          -- Trader Logic (Match shop owner to logged in ID)',
'          (UPPER(:F_USER_ROLE) = ''TRADER'' AND s.user_id = :F_TRADER_ID)',
'    )',
'    GROUP BY u.firstname, u.lastname, s.name',
'    ORDER BY s.name',
'  ) LOOP',
'    APEX_JSON.OPEN_OBJECT;',
'    APEX_JSON.WRITE(''TRADER_NAME'',   r.trader_name);',
'    APEX_JSON.WRITE(''SHOP_NAME'',     r.shop_name);',
'    APEX_JSON.WRITE(''ORDER_COUNT'',   r.order_count);',
'    APEX_JSON.WRITE(''TOTAL_PAYMENT'', r.total_payment);',
'    APEX_JSON.CLOSE_OBJECT;',
'  END LOOP;',
'',
'  APEX_JSON.CLOSE_ARRAY;',
'  APEX_JSON.CLOSE_OBJECT;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>158473833882820303939
);
end;
