wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(158473833937029303940)
,p_plug_name=>'MONTHLY SALES REPORT'
,p_title=>'Monthly Sales Report'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>4072358936313175081
,p_plug_display_sequence=>10
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<style>',
'/* CSS - Keeping your exact layout */',
'*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }',
'body { background: #f7f5f0; }',
'.rpt-wrapper { max-width: 820px; margin: 0 auto; padding: 2rem 1rem; font-family: Georgia, serif; }',
'.rpt-title { font-size: 48px; font-weight: 700; color: #111; margin-bottom: 1.5rem; }',
'.rpt-card { background: #fff; border: 1.5px solid #1a1a1a; border-radius: 4px; padding: 2rem 2rem 1.5rem; margin-bottom: 2rem; }',
'.rpt-card-header { text-align: center; border-bottom: 1.5px solid #1a1a1a; padding-bottom: 1rem; margin-bottom: 1.5rem; }',
'.rpt-card-title { font-size: 20px; font-weight: 600; letter-spacing: 0.3px; }',
'.rpt-meta { font-size: 13px; color: #555; margin-top: 5px; display: flex; align-items: center; justify-content: center; gap: 8px; font-family: Arial, sans-serif; flex-wrap: wrap; }',
'.rpt-date-input, .rpt-select, .rpt-select-trader { font-size: 12px; font-family: Arial, sans-serif; border: 1px solid #aaa; border-radius: 3px; padding: 3px 8px; color: #222; background: #fff; cursor: pointer; }',
'.btn-generate { font-size: 12px; background: #1a1a1a; color: #fff; border: none; padding: 4px 12px; border-radius: 3px; cursor: pointer; }',
'.slot-table { width: 100%; border-collapse: collapse; border: 1px solid #ccc; font-size: 14px; font-family: Arial, sans-serif; }',
'.slot-table thead tr { background: #f0ede6; }',
'.slot-table th, .slot-table td { padding: 8px 12px; border-bottom: 1px solid #eee; text-align: left; }',
'.total-row td { font-weight: 600; background: #f0ede6; border-top: 1.5px solid #ccc; }',
'.no-data { text-align: center; padding: 2rem; font-size: 13px; color: #888; font-style: italic; }',
'.label-actions { padding: 0.75rem 0; display: flex; gap: 10px; }',
'.btn-action { font-size: 13px; background: none; border: 1px solid #999; padding: 5px 14px; border-radius: 3px; cursor: pointer; transition: 0.15s; }',
'.btn-action:hover { background: #1a1a1a; color: #fff; }',
'</style>',
'',
'<div class="rpt-wrapper">',
'  <h1 class="rpt-title">Report</h1>',
'  <div class="rpt-card">',
'    <div class="rpt-card-header">',
'      <div class="rpt-card-title">Monthly sales report</div>',
'      <div class="rpt-meta">',
'        <span>Month:</span>',
'        <input type="month" id="rptMonth" class="rpt-date-input" />',
'        ',
'        <!-- Dropdown container for Admin only -->',
'        <span id="traderContainer"></span>',
'',
'        <span>Sort by:</span>',
'        <select id="rptSort" class="rpt-select">',
'          <option value="alpha">Alphabetically</option>',
'          <option value="orders">Total Orders</option>',
'          <option value="income">Total Income</option>',
'        </select>',
'        <button type="button" class="btn-generate" onclick="loadMonthlyReport(event)">Generate</button>',
'      </div>',
'    </div>',
'    <div id="rptBody">',
'      <div class="no-data">Select a month and sort order, then click Generate.</div>',
'    </div>',
'    <div class="label-actions">',
'      <button type="button" class="btn-action" onclick="downloadCSV(event)">Download</button>',
'    </div>',
'  </div>',
'</div>',
'',
'<script>',
'var reportData = [];',
'',
'(function() {',
'  var d = new Date();',
'  var yyyy = d.getFullYear();',
'  var mm = String(d.getMonth()+1).padStart(2,''0'');',
'  document.getElementById(''rptMonth'').value = yyyy+''-''+mm;',
'',
'  // Move APEX Dropdown P13_MONTHLY_SHOP into the layout',
'  var apexDropdown = document.getElementById(''P13_MONTHLY_SHOP'');',
'  if (apexDropdown) {',
'     var container = document.getElementById(''traderContainer'');',
'     container.innerHTML = ''<span>Trader:</span>'';',
'     container.appendChild(apexDropdown);',
'     apexDropdown.classList.add(''rpt-select-trader'');',
'  }',
'})();',
'',
'function renderReport(rows, sortLabel) {',
'  reportData = rows;',
'  var html = ''<div class="slot-block"><div class="slot-label">Sorted by: '' + sortLabel + ''</div>'';',
unistr('  html += ''<table class="slot-table"><thead><tr><th>Product</th><th>Shop</th><th>Total Units</th><th>Total Income (\00A3)</th></tr></thead><tbody>'';'),
'  ',
'  var grandOrders = 0;',
'  var grandIncome = 0;',
'',
'  rows.forEach(function(row) {',
'    grandOrders += parseInt(row.TOTAL_ORDERS);',
'    grandIncome += parseFloat(row.TOTAL_INCOME);',
unistr('    html += ''<tr><td>''+row.PRODUCT_NAME+''</td><td>''+row.SHOP_NAME+''</td><td>''+row.TOTAL_ORDERS+''</td><td>\00A3''+parseFloat(row.TOTAL_INCOME).toFixed(2)+''</td></tr>'';'),
'  });',
'',
unistr('  html += ''<tr class="total-row"><td colspan="2">Grand Total</td><td>''+grandOrders+''</td><td>\00A3''+grandIncome.toFixed(2)+''</td></tr></tbody></table></div>'';'),
'  document.getElementById(''rptBody'').innerHTML = html;',
'}',
'',
'function loadMonthlyReport(e) {',
'  if (e) e.preventDefault();',
'  var val = document.getElementById(''rptMonth'').value;',
'  if (!val) { alert(''Please select a month.''); return; }',
'  var sort = document.getElementById(''rptSort'').value;',
'  var sortLabels = { alpha: ''Alphabetically'', orders: ''Total Orders'', income: ''Total Income'' };',
'',
'  document.getElementById(''rptBody'').innerHTML = ''<div class="no-data">Loading...</div>'';',
'',
'  apex.server.process(''GET_MONTHLY_SALES'', {',
'    pageItems: ''#P13_MONTHLY_SHOP'', // Submit the Admin trader selection',
'    x01: val,',
'    x02: sort',
'  }, {',
'    success: function(data) {',
'      if (data && data.rows && data.rows.length > 0) {',
'        renderReport(data.rows, sortLabels[sort]);',
'      } else {',
'        document.getElementById(''rptBody'').innerHTML = ''<div class="no-data">No sales found for this month.</div>'';',
'      }',
'    }',
'  });',
'}',
'',
'function downloadCSV(e) {',
'  if (e) e.preventDefault();',
'  if (!reportData.length) return;',
'  var csv = ''Product,Shop,Total Orders,Total Income\n'' + reportData.map(r => r.PRODUCT_NAME+'',''+r.SHOP_NAME+'',''+r.TOTAL_ORDERS+'',''+r.TOTAL_INCOME).join(''\n'');',
'  var a = document.createElement(''a'');',
'  a.href = ''data:text/csv;charset=utf-8,'' + encodeURIComponent(csv);',
'  a.download = ''monthly_sales.csv'';',
'  a.click();',
'}',
'</script>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
