wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(158473834006886303941)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GET_MONTHLY_SALES'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  l_month  VARCHAR2(7) := apex_application.g_x01; -- Incoming ''YYYY-MM''',
'  l_sort   VARCHAR2(10) := apex_application.g_x02;',
'  l_year   NUMBER := TO_NUMBER(SUBSTR(l_month, 1, 4));',
'  l_mon    NUMBER := TO_NUMBER(SUBSTR(l_month, 6, 2));',
'  l_role   VARCHAR2(50) := UPPER(NVL(:F_USER_ROLE, ''GUEST''));',
'BEGIN',
'  APEX_JSON.OPEN_OBJECT;',
'  APEX_JSON.OPEN_ARRAY(''rows'');',
'',
'  -- Loop through data with security filter',
'  FOR r IN (',
'    SELECT',
'      p.name                           AS product_name,',
'      s.name                           AS shop_name,',
'      SUM(op.quantity)                 AS total_orders,',
'      SUM(op.quantity * op.unit_price) AS total_income',
'    FROM HUDDER_ORDER o',
'    JOIN ORDER_PRODUCT op  ON o.order_id  = op.order_id',
'    JOIN PRODUCT p         ON p.product_id = op.product_id',
'    JOIN SHOP s            ON s.shop_id    = p.shop_id',
'    WHERE EXTRACT(YEAR FROM o.order_date)  = l_year',
'    AND   EXTRACT(MONTH FROM o.order_date) = l_mon',
'    AND   o.status = ''Completed''',
'    AND (',
'          -- Admin Logic',
'          (l_role = ''ADMIN'' AND (s.shop_id = :P13_MONTHLY_SHOP OR :P13_MONTHLY_SHOP IS NULL))',
'          OR',
'          -- Trader Logic (Match shop owner to logged in ID)',
'          (l_role = ''TRADER'' AND s.user_id = :F_TRADER_ID)',
'    )',
'    GROUP BY p.name, s.name',
'    ORDER BY',
'      CASE WHEN l_sort = ''alpha''  THEN p.name END ASC,',
'      CASE WHEN l_sort = ''orders'' THEN SUM(op.quantity) END DESC,',
'      CASE WHEN l_sort = ''income'' THEN SUM(op.quantity * op.unit_price) END DESC',
'  ) LOOP',
'    APEX_JSON.OPEN_OBJECT;',
'    APEX_JSON.WRITE(''PRODUCT_NAME'', r.product_name);',
'    APEX_JSON.WRITE(''SHOP_NAME'',    r.shop_name);',
'    APEX_JSON.WRITE(''TOTAL_ORDERS'', r.total_orders);',
'    APEX_JSON.WRITE(''TOTAL_INCOME'', r.total_income);',
'    APEX_JSON.CLOSE_OBJECT;',
'  END LOOP;',
'',
'  APEX_JSON.CLOSE_ARRAY;',
'  APEX_JSON.CLOSE_OBJECT;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>158473834006886303941
);
end;
/
