wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(158473834243084303943)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GET_ALL_REVIEWS'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  l_count NUMBER := 0;',
'BEGIN',
'  SELECT COUNT(*) INTO l_count FROM REVIEW;',
'',
'  APEX_JSON.OPEN_OBJECT;',
'  APEX_JSON.WRITE(''count'', l_count);',
'  APEX_JSON.OPEN_ARRAY(''rows'');',
'',
'  IF l_count > 0 THEN',
'    FOR r IN (',
'      SELECT',
'        s.name                             AS shop_name,',
'        u.firstname || '' '' || u.lastname   AS customer_name,',
'        p.name                             AS product_name,',
'        rv.rating,',
'        rv.review_text',
'      FROM REVIEW rv',
'      JOIN HUDDER_USER u  ON u.user_id    = rv.user_id',
'      JOIN PRODUCT p      ON p.product_id = rv.product_id',
'      JOIN SHOP s         ON s.shop_id    = p.shop_id',
'      ORDER BY s.name, rv.rating DESC',
'    ) LOOP',
'      APEX_JSON.OPEN_OBJECT;',
'      APEX_JSON.WRITE(''SHOP_NAME'',     r.shop_name);',
'      APEX_JSON.WRITE(''CUSTOMER_NAME'', r.customer_name);',
'      APEX_JSON.WRITE(''PRODUCT_NAME'',  r.product_name);',
'      APEX_JSON.WRITE(''RATING'',        r.rating);',
'      APEX_JSON.WRITE(''REVIEW_TEXT'',   r.review_text);',
'      APEX_JSON.CLOSE_OBJECT;',
'    END LOOP;',
'  END IF;',
'',
'  APEX_JSON.CLOSE_ARRAY;',
'  APEX_JSON.CLOSE_OBJECT;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>158473834243084303943
);
end;
