'    v_id   NUMBER;',
'BEGIN',
'    -- 1. If Admin hasn''t picked a trader, show a prompt instead of the dashboard',
'    IF :F_USER_ROLE = ''admin'' AND :P15_VIEW_AS_TRADER IS NULL THEN',
'        RETURN ''<div style="background:#fff; border:1px solid #e0e0e0; border-radius:12px; padding:2rem; text-align:center;">',
'                  <p style="color:#888; font-size:16px;">Please select a trader from the dropdown above to view their dashboard.</p>',
'                </div>'';',
'    END IF;',
'',
'    -- 2. Determine which ID to use (Dropdown for Admin, Session ID for Trader)',
'    v_id := NVL(:P15_VIEW_AS_TRADER, :F_TRADER_ID);',
'',
'    -- 3. Get the name',
'    SELECT firstname || '' '' || lastname INTO v_name',
'    FROM HUDDER_USER ',
'    WHERE user_id = v_id;',
'',
'    RETURN ''<div style="background:#fff; border:1px solid #e0e0e0; border-radius:12px; padding:1.5rem 2rem; display:flex; align-items:center; justify-content:space-between;">',
'      <div>',
'        <p style="font-size:13px; color:#888; margin:0;">Welcome back,</p>',
'        <h2 style="font-size:22px; font-weight:700;">'' || v_name || ''</h2>',
'      </div>',
'      <div style="text-align:right;"><span style="font-size:12px; background:#E1F5EE; color:#0F6E56; padding:4px 12px; border-radius:6px; font-weight:600;">Active Trader</span></div>',
'    </div>'';',
'EXCEPTION WHEN OTHERS THEN ',
'    RETURN ''Welcome to Hudders Hub.'';',
'END;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
,p_ajax_items_to_submit=>'P15_VIEW_AS_TRADER, F_TRADER_ID'
