 p_id=>wwv_flow_imp.id(159759575533746802310)
,p_plug_name=>'Today''s Orders'
,p_title=>'Today''s Orders'
,p_icon_css_classes=>'fa-shopping-bag'
,p_region_template_options=>'#DEFAULT#:t-Region--noBorder:t-Region--scrollBody'
,p_plug_template=>4072358936313175081
,p_plug_display_sequence=>30
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'  cs.slot_time                    AS card_title,',
'  COUNT(DISTINCT o.order_id) || '' Orders'' AS card_subtitle,',
'  SUM(op.quantity) || '' Total Items''     AS card_body,',
'  o.status                        AS card_badge,',
'  ''fa-shopping-basket''            AS card_icon',
'FROM HUDDER_ORDER o',
'JOIN ORDER_PRODUCT op        ON op.order_id  = o.order_id',
'JOIN PRODUCT p               ON p.product_id = op.product_id',
'JOIN SHOP s                  ON s.shop_id    = p.shop_id',
'JOIN HUDDER_USER u           ON u.user_id    = s.user_id',
'LEFT JOIN COLLECTION_SLOT cs ON cs.slot_id   = o.slot_id',
'WHERE TRUNC(o.order_date) = TRUNC(SYSDATE)',
'  AND u.user_id = NVL(:P15_VIEW_AS_TRADER, :F_TRADER_ID)',
'  AND (:F_USER_ROLE = ''trader'' OR (:F_USER_ROLE = ''admin'' AND :P15_VIEW_AS_TRADER IS NOT NULL))',
'GROUP BY cs.slot_time, o.status'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_ajax_items_to_submit=>'F_TRADER_ID, P15_VIEW_AS_TRADER'
,p_plug_query_num_rows_type=>'SCROLL'
,p_show_total_row_count=>false
);
