,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'  p.name                                    AS card_title,',
'  ''Current Stock: '' || p.stock              AS card_subtitle,',
'  ''Minimum required: '' || p.reorder_label   AS card_body,',
'  CASE ',
'    WHEN p.stock = 0 THEN ''OUT OF STOCK'' ',
'    ELSE ''LOW STOCK'' ',
'  END                                       AS card_badge,',
'  -- Color: Red (u-color-9) for 0 stock, Orange (u-color-7) for Low stock',
'  CASE ',
'    WHEN p.stock = 0 THEN ''u-color-9'' ',
'    ELSE ''u-color-7'' ',
'  END                                       AS card_color',
'FROM PRODUCT p',
'JOIN SHOP s       ON s.shop_id  = p.shop_id',
'JOIN HUDDER_USER u ON u.user_id = s.user_id',
'WHERE u.user_id = NVL(:P15_VIEW_AS_TRADER, :F_TRADER_ID)',
'  AND p.stock <= p.reorder_label',
'  AND (:F_USER_ROLE = ''trader'' OR (:F_USER_ROLE = ''admin'' AND :P15_VIEW_AS_TRADER IS NOT NULL))',
'ORDER BY p.stock ASC'))
