wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(159759576707823802322)
,p_name=>'Recent Reviews'
,p_title=>'Recent Reviews'
,p_template=>4072358936313175081
,p_display_sequence=>60
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--altRowsDefault:t-Report--rowHighlight'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'  p.name                                AS "Product",',
'  u.firstname || '' '' || u.lastname      AS "Customer",',
'  rv.rating                             AS "Rating",',
'  CASE',
unistr('    WHEN rv.rating >= 4 THEN ''<span style="color:#c8a84b;font-size:14px;">\2605\2605\2605\2605\2605</span>'''),
unistr('    WHEN rv.rating >= 3 THEN ''<span style="color:#c8a84b;font-size:14px;">\2605\2605\2605\2605\2606</span>'''),
unistr('    WHEN rv.rating >= 2 THEN ''<span style="color:#c8a84b;font-size:14px;">\2605\2605\2605\2606\2606</span>'''),
unistr('    ELSE                     ''<span style="color:#c8a84b;font-size:14px;">\2605\2605\2606\2606\2606</span>'''),
'  END                                   AS "Stars",',
'  NVL(rv.review_text, ''No comment'')     AS "Review"',
'FROM REVIEW rv',
'JOIN HUDDER_USER u  ON u.user_id    = rv.user_id',
'JOIN PRODUCT p      ON p.product_id = rv.product_id',
'JOIN SHOP s         ON s.shop_id    = p.shop_id',
'JOIN HUDDER_USER tu ON tu.user_id   = s.user_id',
'WHERE tu.email = :APP_USER',
'ORDER BY rv.review_id DESC',
'FETCH FIRST 5 ROWS ONLY'))
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>2538654340625403440
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_num_rows_type=>'NEXT_PREVIOUS_LINKS'
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
);
