wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(162937565351379260535)
,p_plug_name=>'Stock Management'
,p_title=>'Stock Levels'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2100526641005906379
,p_plug_display_sequence=>20
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    p.product_id,',
'    p.name AS product_name,',
'    s.name AS shop_name,',
'    p.price,',
'    p.stock,',
'    p.reorder_label, -- This is your ''minimum stock'' level from the script',
'    -- Indicator for low stock',
'    CASE ',
'        WHEN p.stock <= p.reorder_label THEN ''Low Stock''',
'        WHEN p.stock = 0 THEN ''Out of Stock''',
'        ELSE ''Healthy''',
'    END AS stock_status',
'FROM PRODUCT p',
'JOIN SHOP s ON p.shop_id = s.shop_id',
'WHERE ',
'    (UPPER(:F_USER_ROLE) = ''ADMIN'' AND (s.shop_id = :P16_SHOP_FILTER OR :P16_SHOP_FILTER IS NULL))',
'    OR',
'    (UPPER(:F_USER_ROLE) = ''TRADER'' AND s.user_id = :F_TRADER_ID)'))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P16_SHOP_FILTER'
,p_prn_page_header=>'Stock Management'
);
