,p_process_name=>'PROCESS_TRADER_CRUD'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    IF :P18_USER_ID IS NULL THEN',
'        -- INSERT LOGIC',
'        INSERT INTO HUDDER_USER (firstname, lastname, email, user_password, user_role, phone_number, address)',
'        VALUES (:P18_FIRSTNAME, :P18_LASTNAME, :P18_EMAIL, :P18_USER_PASSWORD, ''trader'', :P18_PHONE_NUMBER, :P18_ADDRESS)',
'        RETURNING user_id INTO :P18_USER_ID;',
'',
'        INSERT INTO TRADER (user_id, status) VALUES (:P18_USER_ID, :P18_STATUS);',
'        INSERT INTO SHOP (name, user_id) VALUES (:P18_SHOP_NAME, :P18_USER_ID);',
'    ELSE',
'        -- UPDATE LOGIC',
'        UPDATE HUDDER_USER SET firstname = :P18_FIRSTNAME, lastname = :P18_LASTNAME, email = :P18_EMAIL, phone_number = :P18_PHONE_NUMBER, address = :P18_ADDRESS WHERE user_id = :P18_USER_ID;',
'        UPDATE TRADER SET status = :P18_STATUS WHERE user_id = :P18_USER_ID;',
'        UPDATE SHOP SET name = :P18_SHOP_NAME WHERE user_id = :P18_USER_ID;',
'    END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>':REQUEST IN (''CREATE'', ''SAVE'')'
