begin
wwv_flow_imp_page.create_page(
 p_id=>22
,p_name=>'Discounts & Promotions'
,p_alias=>'DISCOUNTS-PROMOTIONS'
,p_step_title=>'Discounts & Promotions'
,p_autocomplete_on_off=>'OFF'
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'23'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(162677717475462631576)
,p_plug_name=>'Breadcrumb'
,p_region_template_options=>'#DEFAULT#:t-BreadcrumbRegion--useBreadcrumbTitle'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>2531463326621247859
,p_plug_display_sequence=>10
,p_plug_display_point=>'REGION_POSITION_01'
,p_menu_id=>wwv_flow_imp.id(151805151793761863167)
,p_plug_source_type=>'NATIVE_BREADCRUMB'
,p_menu_template_id=>4072363345357175094
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(162677718172218631578)
,p_plug_name=>'Discounts & Promotions'
,p_region_template_options=>'#DEFAULT#:t-CardsRegion--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2072724515482255512
,p_plug_display_sequence=>10
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    d.discount_id,',
'    d.discount_type AS sale_event,          -- Uses ''Seasonal'', ''Festival'', etc.',
'    d.discount_percent || ''%'' AS badge_val, -- Shows ''10%'', ''25%''',
'    p.name AS product_name,                 -- Product getting the discount',
'    s.name AS shop_name,                    -- Shop offering it',
'    u.firstname || '' '' || u.lastname AS trader_name,',
'    ''Expires: '' || TO_CHAR(d.valid_until, ''DD-Mon-YYYY'') AS expiry_label,',
'    -- Color Logic',
'    CASE ',
'        WHEN d.valid_until >= TRUNC(sysdate) THEN ''Active'' ',
'        ELSE ''Expired'' ',
'    END AS sale_status,',
'    CASE ',
'        WHEN d.valid_until >= TRUNC(sysdate) THEN ''u-color-2'' -- Green for Active',
'        ELSE ''u-color-3'' -- Grey for Expired',
'    END AS status_color',
'FROM DISCOUNT d',
'JOIN PRODUCT p ON d.product_id = p.product_id',
'JOIN SHOP s ON p.shop_id = s.shop_id',
'JOIN HUDDER_USER u ON s.user_id = u.user_id',
'WHERE ',
'    -- Security: Admin sees all, Trader sees only their shop''s items',
'    (UPPER(:F_USER_ROLE) = ''ADMIN''AND (u.user_id = :P22_TRADER_SELECTOR OR :P22_TRADER_SELECTOR IS NULL))',
'    OR',
'    (UPPER(:F_USER_ROLE) = ''TRADER'' AND s.user_id = :F_TRADER_ID)'))
,p_query_order_by_type=>'ITEM'
,p_query_order_by=>'{ "itemName": "P22_ORDER_BY", "orderBys": [{"key":"SALE_EVENT","expr":"\"SALE_EVENT\" asc"},{"key":"PRODUCT_NAME","expr":"\"PRODUCT_NAME\" asc"},{"key":"BADGE_VAL","expr":"\"BADGE_VAL\" asc"}]}'
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_ajax_items_to_submit=>'P22_TRADER_SELECTOR'
,p_plug_query_num_rows=>15
,p_plug_query_num_rows_type=>'SCROLL'
,p_show_total_row_count=>false
,p_pagination_display_position=>'BOTTOM_RIGHT'
);
wwv_flow_imp_page.create_card(
 p_id=>wwv_flow_imp.id(162677718692957631579)
,p_region_id=>wwv_flow_imp.id(162677718172218631578)
