begin
wwv_flow_imp_page.create_page(
 p_id=>24
,p_name=>'Notifications'
,p_alias=>'NOTIFICATIONS'
,p_step_title=>'Notifications'
,p_autocomplete_on_off=>'OFF'
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'23'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(162689817980314724508)
,p_plug_name=>'Breadcrumb'
,p_region_template_options=>'#DEFAULT#:t-BreadcrumbRegion--useBreadcrumbTitle'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>2531463326621247859
,p_plug_display_sequence=>10
,p_plug_display_point=>'REGION_POSITION_01'
,p_location=>null
,p_menu_id=>wwv_flow_imp.id(151805151793761863167)
,p_plug_source_type=>'NATIVE_BREADCRUMB'
,p_menu_template_id=>4072363345357175094
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(162689818684987724509)
,p_plug_name=>'Notifications'
,p_region_template_options=>'#DEFAULT#:t-CardsRegion--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2072724515482255512
,p_plug_display_sequence=>10
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- 1. TRADER: NEW ORDERS ALERT',
'SELECT ',
'    ''NEW_ORDER'' as alert_type,',
'    ''New Order Received'' as title,',
'    ''Order #'' || o.order_id || '' for '' || u.firstname || '' is pending.'' as description,',
'    ''fa-shopping-cart'' as icon,',
'    ''u-color-1'' as alert_color,',
'    o.order_date as alert_date',
'FROM HUDDER_ORDER o',
'JOIN HUDDER_USER u ON o.user_id = u.user_id',
'JOIN ORDER_PRODUCT op ON o.order_id = op.order_id',
'JOIN PRODUCT p ON op.product_id = p.product_id',
'JOIN SHOP s ON p.shop_id = s.shop_id',
'WHERE o.status = ''Pending''',
'AND TRUNC(o.order_date) = TRUNC(sysdate)',
'AND (:F_USER_ROLE = ''trader'' AND s.user_id = :F_TRADER_ID)',
'',
'UNION ALL',
'',
'-- 2. TRADER: LOW STOCK ALERT',
'SELECT ',
'    ''LOW_STOCK'',',
'    ''Low Stock Warning'',',
'    ''Product '' || p.name || '' only has '' || p.stock || '' left!'',',
'    ''fa-exclamation-triangle'',',
'    ''u-color-9'', -- Red/Orange',
'    sysdate',
'FROM PRODUCT p',
'JOIN SHOP s ON p.shop_id = s.shop_id',
'WHERE p.stock < 5',
'AND (:F_USER_ROLE = ''trader'' AND s.user_id = :F_TRADER_ID)',
'',
'UNION ALL',
'',
'-- 3. ADMIN: PENDING TRADERS',
'SELECT ',
'    ''PENDING_TRADER'',',
'    ''Trader Approval Needed'',',
'    u.firstname || '' '' || u.lastname || '' is waiting for account activation.'',',
'    ''fa-user-clock'',',
'    ''u-color-7'',',
'    sysdate',
'FROM TRADER t',
'JOIN HUDDER_USER u ON t.user_id = u.user_id',
'WHERE t.status = ''Pending''',
'AND :F_USER_ROLE = ''admin''',
'',
'UNION ALL',
'',
'-- 4. ADMIN: SLOT CAPACITY ALERT',
'SELECT ',
'    ''FULL_SLOT'',',
'    ''Capacity Alert'',',
'    ''Slot '' || cs.slot_time || '' on '' || TO_CHAR(cs.slot_date, ''DD-Mon'') || '' is almost full!'',',
